inline constexpr uint32_t kVoRangeCount = 2427;

// Binary search over kVoRanges (sorted, non-overlapping by construction from the
// source file). Returns Upright for any codepoint not covered by an explicit
// range (the source file's documented default).
inline VerticalOrientation verticalOrientation(uint32_t codepoint) {
    uint32_t lo = 0;
    uint32_t hi = kVoRangeCount;
    while (lo < hi) {
        const uint32_t mid = lo + (hi - lo) / 2;
        const VoRange& r = kVoRanges[mid];
        if (codepoint < r.first) {
            hi = mid;
        } else if (codepoint > r.last) {
            lo = mid + 1;
        } else {
            return static_cast<VerticalOrientation>(r.value);
        }
    }
    return VerticalOrientation::Upright;
}

